import{_ as r,o,c as e,a6 as n}from"./chunks/framework.BrkgobfX.js";const m=JSON.parse('{"title":"训练侧的花样 · MTP、FP8、Muon","description":"两个模型架构图一模一样，训练方式也能拉开差距。看不改推理样子、却决定“训得多快多省多好”的三个花样：DeepSeek 的多 token 预测（MTP）与 DSpark、FP8/FP4 低精度训练，以及 Kimi 大规模押注的 Muon 优化器。","frontmatter":{"title":"训练侧的花样 · MTP、FP8、Muon","description":"两个模型架构图一模一样，训练方式也能拉开差距。看不改推理样子、却决定“训得多快多省多好”的三个花样：DeepSeek 的多 token 预测（MTP）与 DSpark、FP8/FP4 低精度训练，以及 Kimi 大规模押注的 Muon 优化器。","source":"https://daiw.org/manual/llm-anatomy/training-tricks"},"headers":[],"relativePath":"manual/llm/llm-anatomy/training-tricks.md","filePath":"manual/llm/llm-anatomy/training-tricks.md"}'),a={name:"manual/llm/llm-anatomy/training-tricks.md"};function s(l,t,i,g,p,k){return o(),e("div",null,[...t[0]||(t[0]=[n('<h1 id="训练侧的花样-·-mtp、fp8、muon" tabindex="-1">训练侧的花样 · MTP、FP8、Muon <a class="header-anchor" href="#训练侧的花样-·-mtp、fp8、muon" aria-label="Permalink to &quot;训练侧的花样 · MTP、FP8、Muon&quot;">​</a></h1><blockquote><p>两个模型架构图一模一样，训练方式也能拉开差距。看不改推理样子、却决定“训得多快多省多好”的三个花样：DeepSeek 的多 token 预测（MTP）与 DSpark、FP8/FP4 低精度训练，以及 Kimi 大规模押注的 Muon 优化器。</p></blockquote><p>前面几章拆的都是“模型长什么样”。但有一类差异，<strong>在架构图上根本看不见</strong>——它藏在<strong>怎么训练</strong>里。两个结构一模一样的模型，训练方式不同，成本和质量能差出一大截。这一章挑三个有代表性的花样。它们有个共同点：<strong>不改变模型主干推理时的样子，只影响“训得多快、多省、多好”。</strong></p><h2 id="mtp-与-dspark-一次预测好几个-token" tabindex="-1">MTP（与 DSpark）：一次预测好几个 token <a class="header-anchor" href="#mtp-与-dspark-一次预测好几个-token" aria-label="Permalink to &quot;MTP（与 DSpark）：一次预测好几个 token&quot;">​</a></h2><p>回忆 <a href="https://daiw.org/manual/nanogpt/model-overview" target="_blank" rel="noreferrer">nanoGPT 的训练</a>：每个位置，模型只预测<strong>下一个</strong> token，和真实答案比、算 loss。这是几十年的标准做法。</p><p><strong>多 token 预测（Multi-Token Prediction，MTP）</strong> 问：为什么一次只预测一个？<strong>让每个位置同时预测未来好几个 token 呢？</strong> 加几个额外的预测头，一个管“下一个”、一个管“下下个”……</p><p><strong>Gloeckle et al.（Meta，2024）</strong> 证明这么做有两重好处：</p><ol><li><strong>样本效率更高</strong>：逼模型“往前多想几步”，学到的表示更有规划性，同样的数据能学得更好；</li><li><strong>推理还能白捡个加速</strong>：那些“预测未来”的头，天然适合做<strong>投机解码（speculative decoding）</strong>——先让它一口气猜几个，再让主模型验证，验证通过就一次吐好几个，生成变快。</li></ol><p><strong>DeepSeek-V3 把 MTP 用作训练目标</strong>（预测未来 2 个 token），既提升了主模型质量，又为推理留了投机解码的抓手；<a href="https://daiw.org/manual/qwen3-8-max/architecture" target="_blank" rel="noreferrer">Qwen3.8-Max</a> 也继承了单步 MTP 头。而到了 2026 年的 <a href="https://daiw.org/manual/deepseek-v4-flash/engram-dspark" target="_blank" rel="noreferrer">DeepSeek V4.1-Flash</a>，团队干脆把链式串行的 MTP 替换成了参数量仅 <strong>4.3B</strong> 的单层全稠密并行草稿头 <strong>DSpark</strong>——它直接复用目标解码器最后一层的隐藏状态和 KV 缓存，一次前向并行吐出最多 16 个候选 token，单批次解码吞吐提升可达 3.93 倍（官方报告）。</p><h2 id="fp8-与原生-fp4-用低精度把训练和推理成本砍半" tabindex="-1">FP8（与原生 FP4）：用低精度把训练和推理成本砍半 <a class="header-anchor" href="#fp8-与原生-fp4-用低精度把训练和推理成本砍半" aria-label="Permalink to &quot;FP8（与原生 FP4）：用低精度把训练和推理成本砍半&quot;">​</a></h2><p>模型训练要在<strong>数值精度</strong>和<strong>成本</strong>之间权衡。大多数早期模型用 <strong>bf16 / fp16</strong>（16 位浮点）训练。DeepSeek-V3 更进一步：<strong>大部分计算用 FP8（8 位浮点）</strong>。</p><p>这是什么概念？<strong>位数减半，显存和带宽的压力就大致减半</strong>——对一个 671B、烧几百万美元电费的训练来说，这是实打实的省钱。但 FP8 极难驾驭：<strong>8 位能表示的数值范围窄得可怜</strong>，稍不留神就“精度不够、数值溢出/归零”，训练直接崩。</p><p>DeepSeek-V3 的贡献，是把 FP8 训练<strong>在 671B 这个规模上真正跑通了</strong>：靠<strong>细粒度的分块缩放</strong>（不同区块各自选合适的数值范围）等一整套精细手艺，把精度损失压到可接受。</p><p>到了 2026 年，伴随着 NVIDIA Blackwell（B200/GB200）硬件普及，各家进一步把战线推到了 <strong>4 位浮点（FP4 / MXFP4）</strong>：</p><ul><li><a href="https://daiw.org/manual/deepseek-v4-flash/fp8-fp4" target="_blank" rel="noreferrer">DeepSeek V4.1-Flash</a> 原生支持 <strong>FP4 KV 缓存</strong>与 <strong>NVFP4 权重量化</strong>；</li><li><a href="https://daiw.org/manual/qwen3-8-max/open-weights" target="_blank" rel="noreferrer">Qwen3.8-Max</a> 发布即提供官方原生 <strong>FP8</strong> 权重（<code>Qwen3.8-2.4T-A95B-FP8</code>）；</li><li><a href="https://daiw.org/manual/kimi-k3/deploy" target="_blank" rel="noreferrer">Kimi K3 / K3.1 Pro</a> 则在预训练末段引入量化感知训练（QAT），把占全模型参数绝大部分的 896 个路由专家直接发布为原生 <strong>MXFP4</strong>（4-bit 微缩放浮点），让 2.8T 参数的巨无霸能装进单台 8×B200 节点。</li></ul><div class="info custom-block"><p class="custom-block-title">INFO</p><p>把 DeepSeek 的省钱账拼起来看，特别能说明“差异是叠出来的”：<strong>MLA / CSA2</strong>（省 KV 缓存）+ <strong>细粒度 MoE</strong>（省激活算力）+ <strong>无辅助损失均衡</strong>（不牺牲质量地均衡）+ <strong>FP8 / FP4</strong>（省训练与推理精度成本）+ <strong>MTP / DSpark</strong>（提样本效率与解码吞吐）。没有哪一招是“银弹”，是这一串选择<strong>共同</strong>造就了“又强又便宜”。读架构，读的就是这种组合拳。</p></div><h2 id="muon-换个优化器-赌-更聪明的每一步" tabindex="-1">Muon：换个优化器，赌“更聪明的每一步” <a class="header-anchor" href="#muon-换个优化器-赌-更聪明的每一步" aria-label="Permalink to &quot;Muon：换个优化器，赌“更聪明的每一步”&quot;">​</a></h2><p>几乎所有 LLM 都用 <strong>AdamW</strong> 优化器（nanoGPT 也是，那个专栏会逐行讲它）。它久经考验，是默认中的默认。</p><p><strong>Muon（Keller Jordan et al.，2024）</strong> 是个新优化器，思路是<strong>对参数更新做“正交化”</strong>（用 Newton-Schulz 迭代把动量矩阵近似正交化），让每一步更新的“方向”更有效、信息利用更充分——<strong>同样的步数，走得更远、更准</strong>。</p><p>它的分水岭时刻是 <strong>Kimi K2（Moonshot，2025）</strong>：<strong>第一次在 1T 参数这种超大规模、生产级训练里押注 Muon</strong>（此前 Muon 只在 ~16B 级别验证过）。到了 2026 年的 <strong><a href="https://daiw.org/manual/kimi-k3/pretrain-scaling" target="_blank" rel="noreferrer">Kimi K3</a></strong>，Moonshot 进一步用 Muon 配合 QK-Clip 和 Token 预算迁移定律，把模型规模一举推上了 <strong>2.8T 总参数</strong>。这是一个很干脆的赌注：<strong>与其堆更多重复 token，不如用更聪明的二阶正交化优化器，把每一步的样本效率榨干。</strong></p><p>Muon 能不能像 AdamW 那样成为全行业默认，还得时间检验。但它代表了一个常被忽视的差异轴：<strong>优化器</strong>——模型架构之外，“怎么走下山”这件事本身，也是各家可以下注的地方。</p><h2 id="小结-看不见-但很关键" tabindex="-1">小结：看不见，但很关键 <a class="header-anchor" href="#小结-看不见-但很关键" aria-label="Permalink to &quot;小结：看不见，但很关键&quot;">​</a></h2><p>这三个花样——MTP / DSpark、FP8 / FP4、Muon——都不改变主干推理的计算图，却分别动了<strong>训练目标与投机头、数值精度、优化器</strong>。它们提醒我们：</p><blockquote><p><strong>“模型架构”只是故事的一半。同一副骨架，用不同的目标、精度、优化器去训，得到的成本和质量可以天差地别。</strong></p></blockquote><p>架构维度和训练维度都铺开了。还剩最后一撮“小执念”——宽还是深、注意力里那个古老的 bias、attention sink、词表大小——它们各自不大，但凑起来也是各家的指纹。这是收尾前的最后一块拼图。👉 <a href="/Front2Full/manual/llm/llm-anatomy/width-depth-quirks">宽还是深，以及那些小执念</a></p><h2 id="参考文献" tabindex="-1">参考文献 <a class="header-anchor" href="#参考文献" aria-label="Permalink to &quot;参考文献&quot;">​</a></h2><ul><li>[1] Gloeckle et al. (Meta). “Better &amp; Faster Large Language Models via Multi-token Prediction.” 2024. arXiv:2404.19737. —— MTP。</li><li>[2] DeepSeek-AI. “DeepSeek-V3 Technical Report.” 2024. arXiv:2412.19437. —— MTP 训练目标 + FP8 大规模训练。</li><li>[3] Micikevicius et al. “Mixed Precision Training.” ICLR 2018. arXiv:1710.03740. —— 混合精度训练的基础。</li><li>[4] Liu et al. (Moonshot AI). “Muon is Scalable for LLM Training.” 2025. arXiv:2502.16982. —— Muon 的大规模可扩展性（Kimi K2/K3 背景）。</li><li>[5] Loshchilov &amp; Hutter. “Decoupled Weight Decay Regularization (AdamW).” ICLR 2019. arXiv:1711.05101. —— 作为对照的主流优化器。</li></ul>',27)])])}const c=r(a,[["render",s]]);export{m as __pageData,c as default};
